export default {
  /**
   * Main request handler
   */
  async fetch(request, env) {
    /**
     * Small helper to build HTML responses (success + error)
     */
    const html = (
      { title, body, isError = false, extraHeaders = {} },
    ) =>
      new Response(
        `<!DOCTYPE html>
         <html lang="en">
           <head>
             <meta charset="utf-8">
             <title>${title}</title>
             <style>
               body{font-family:-apple-system,system-ui,sans-serif;
                    max-width:680px;margin:3rem auto;padding:0 1rem;text-align:center;}
               .card{border:1px solid ${isError ? "#ffcdd2" : "#c8e6c9"};
                     background:${isError ? "#ffebee" : "#e8f5e9"};
                     padding:1rem;border-radius:6px;}
               img{border-radius:50%;vertical-align:middle;margin-right:.5rem}
               ul{list-style:none;padding:0}
             </style>
           </head>
           <body>
             <div class="card">${body}</div>
             ${isError
          ? "<p>Please close this window and try again.</p>"
          : ""}
           </body>
         </html>`,
        {
          status: isError ? 400 : 200,
          headers: { "Content-Type": "text/html", ...extraHeaders },
        },
      );

    try {
      const url = new URL(request.url);

      // =============== 1. First visit → kick off OAuth flow ===============
      if (!url.searchParams.has("code")) {
        // Anti-CSRF state value
        const state = crypto.randomUUID();

        const authURL = new URL("https://accounts.google.com/o/oauth2/v2/auth");
        authURL.searchParams.set("client_id", env.GOOGLE_CLIENT_ID);
        authURL.searchParams.set("redirect_uri", env.GOOGLE_REDIRECT_URI);
        authURL.searchParams.set("response_type", "code");
        authURL.searchParams.set(
          "scope",
          "https://www.googleapis.com/auth/youtube.readonly",
        );
        authURL.searchParams.set("state", state);
        authURL.searchParams.set("access_type", "offline"); // ask for refresh_token

        return new Response(null, {
          status: 302,
          headers: {
            Location: authURL.toString(),
            "Set-Cookie":
              `yt_state=${state}; HttpOnly; Secure; SameSite=Lax; Max-Age=3600; Path=/`,
          },
        });
      }

      // =============== 2. Callback request ===============
      const { code, state: returnedState } = Object.fromEntries(
        url.searchParams,
      );

      // 2a. Validate state cookie to mitigate CSRF
      const cookieHeader = request.headers.get("Cookie") || "";
      const savedState = cookieHeader
        .split(";")
        .map((c) => c.trim())
        .find((c) => c.startsWith("yt_state="))
        ?.split("=")[1];

      const clearStateCookie =
        "yt_state=; HttpOnly; Secure; SameSite=Lax; Max-Age=0; Path=/";

      if (!savedState || savedState !== returnedState) {
        return html({
          title: "Security error",
          body:
            "<h2>Invalid state parameter.</h2><p>Potential CSRF detected.</p>",
          isError: true,
          extraHeaders: { "Set-Cookie": clearStateCookie },
        });
      }

      // 2b. Exchange code for access_token
      const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          code,
          client_id: env.GOOGLE_CLIENT_ID,
          client_secret: [REDACTED],
          redirect_uri: env.GOOGLE_REDIRECT_URI,
          grant_type: "authorization_code",
        }),
      });

      const tokenJson = await tokenRes.json();
      if (tokenJson.error) {
        return html({
          title: "OAuth error",
          body: `<h2>${tokenJson.error}</h2><p>${tokenJson.error_description ??
            ""}</p>`,
          isError: true,
          extraHeaders: { "Set-Cookie": clearStateCookie },
        });
      }

      const accessToken = [REDACTED];

      // 2c. Call YouTube Data API to fetch subscriptions
      const ytRes = await fetch(
        "https://www.googleapis.com/youtube/v3/subscriptions?part=snippet&mine=true&maxResults=50",
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );

      if (!ytRes.ok) {
        return html({
          title: "YouTube API error",
          body:
            `<h2>Unable to fetch subscriptions.</h2><p>Status: ${ytRes.status}</p>`,
          isError: true,
          extraHeaders: { "Set-Cookie": clearStateCookie },
        });
      }

      const ytJson = await ytRes.json();

      const listItems = ytJson.items
        .map(
          (sub) =>
            `<li><img src="${sub.snippet.thumbnails.default.url}" width="40" height="40" alt="">
             ${sub.snippet.title}</li>`,
        )
        .join("");

      return html({
        title: "Your YouTube Subscriptions",
        body:
          `<h2>Subscriptions (${ytJson.items.length})</h2><ul>${listItems}</ul>
           <p>You can close this window now.</p>`,
        extraHeaders: { "Set-Cookie": clearStateCookie },
      });
    } catch (err) {
      return html({
        title: "Unexpected error",
        body: `<h2>Unexpected error</h2><p>${err.message}</p>`,
        isError: true,
      });
    }
  },
};

export default {
  async fetch(request, env) {
    const generateHTML = ({ title, content, isError = false, headers = {} }) => {
      return new Response(`
        <!DOCTYPE html>
        <html>
          <head>
            <title>${title}</title>
            <style>
              body {
                font-family: -apple-system, system-ui, sans-serif;
                padding: 2rem;
                max-width: 600px;
                margin: 0 auto;
                text-align: center;
              }
              .message {
                padding: 1rem;
                margin: 1rem 0;
                border-radius: 4px;
                background-color: ${isError ? '#ffebee' : '#e8f5e9'};
                border: 1px solid ${isError ? '#ffcdd2' : '#c8e6c9'};
                color: ${isError ? '#b71c1c' : '#2e7d32'};
              }
            </style>
          </head>
          <body>
            <div class="message">
              ${content}
            </div>
            ${isError ? '<p>Please close this window and try again. If the problem persists, contact support.</p>' : ''}
          </body>
        </html>
      `, {
        headers: {
          'Content-Type': 'text/html',
          ...headers
        },
        status: isError ? 400 : 200
      });
    };

    try {
      const url = new URL(request.url);
      const clientId = env.GITHUB_CLIENT_ID;
      const clientSecret = [REDACTED];
      const redirectUri = env.GITHUB_REDIRECT_URI;

      if (!url.searchParams.has('code')) {
        // Initial authorization request
        const state = crypto.randomUUID();
        const githubAuthUrl = new URL('https://github.com/login/oauth/authorize');
        githubAuthUrl.searchParams.set('client_id', clientId);
        githubAuthUrl.searchParams.set('redirect_uri', redirectUri);
        githubAuthUrl.searchParams.set('scope', 'gist');
        githubAuthUrl.searchParams.set('state', state);

        // Create headers object with the state cookie
        const headers = new Headers({
          'Location': githubAuthUrl.toString(),
          'Set-Cookie': `github_auth_state=${state}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=3600`
        });

        return new Response(null, {
          status: 302,
          headers
        });
      }

      // Callback handling
      const returnedState = url.searchParams.get('state');
      const cookies = request.headers.get('Cookie') || '';
      const stateCookie = cookies.split(';')
        .map(cookie => cookie.trim())
        .find(cookie => cookie.startsWith('github_auth_state='));
      const savedState = stateCookie ? stateCookie.split('=')[1] : null;

      // Cookie cleanup header
      const clearStateCookie = {
        'Set-Cookie': 'github_auth_state=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0'
      };

      // Validate state parameter
      if (!savedState || savedState !== returnedState) {
        return generateHTML({
          title: 'Invalid State Parameter',
          content: `
            <h3>Security Error</h3>
            <p>Invalid state parameter detected. This could indicate a CSRF attempt.</p>
          `,
          isError: true,
          headers: clearStateCookie
        });
      }

      const tokenResponse = await fetch('https://github.com/login/oauth/access_token', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify({
          client_id: clientId,
          client_secret: [REDACTED],
          code: url.searchParams.get('code'),
          redirect_uri: redirectUri,
          state: returnedState
        })
      });

      const tokenData = await tokenResponse.json();

      if (tokenData.error) {
        return generateHTML({
          title: 'GitHub OAuth Error',
          content: `
            <h3>Authentication Error</h3>
            <p>Error: ${tokenData.error}</p>
            ${tokenData.error_description ? `<p>Description: ${tokenData.error_description}</p>` : ''}
          `,
          isError: true,
          headers: clearStateCookie
        });
      }

      // Success response with cookie cleanup
      return generateHTML({
        title: 'GitHub OAuth Success',
        content: `
          <h2>Authentication successful!</h2>
          <p>You can close this window.</p>
          <script>
            try {
              localStorage.setItem('GITHUB_TOKEN', '${tokenData.access_token}');
            } catch (err) {
              document.body.innerHTML += '<p style="color: #c62828;">Warning: Unable to store token in localStorage</p>';
            }
          </script>
        `,
        headers: clearStateCookie
      });

    } catch (error) {
      // Error response with cookie cleanup
      return generateHTML({
        title: 'Unexpected Error',
        content: `
          <h3>Unexpected Error</h3>
          <p>An unexpected error occurred during authentication.</p>
          <p>Details: ${error.message}</p>
        `,
        isError: true,
        headers: {
          'Set-Cookie': 'github_auth_state=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0'
        }
      });
    }
  }
};

/**
 * llm-lib.js - A unified JavaScript browser library for LLM providers
 * Supports OpenAI, Anthropic (Claude), and Google Gemini
 *
 * Usage:
 *   const llm = new LLM({ provider: 'openai', apiKey: 'sk-...', model: 'gpt-4o' });
 *
 *   // Non-streaming
 *   const response = await llm.prompt('Hello!');
 *
 *   // Streaming
 *   for await (const chunk of llm.stream('Hello!')) {
 *     console.log(chunk);
 *   }
 */

class LLM {
  /**
   * @param {Object} options
   * @param {string} options.provider - 'openai' | 'anthropic' | 'gemini'
   * @param {string} options.apiKey - API key for the provider
   * @param {string} [options.model] - Model to use (defaults per provider)
   * @param {string} [options.systemPrompt] - Optional system prompt
   */
  constructor(options) {
    this.provider = options.provider;
    this.apiKey = [REDACTED];
    this.systemPrompt = options.systemPrompt || null;

    // Set default models per provider
    const defaultModels = {
      openai: 'gpt-4o-mini',
      anthropic: 'claude-3-5-haiku-latest',
      gemini: 'gemini-2.0-flash'
    };
    this.model = options.model || defaultModels[this.provider];

    // Get the appropriate adapter
    this.adapter = LLM.adapters[this.provider];
    if (!this.adapter) {
      throw new Error(`Unknown provider: ${this.provider}. Supported: openai, anthropic, gemini`);
    }
  }

  /**
   * Send a prompt and get a complete response (non-streaming)
   * @param {string|Array} input - Either a string (user message) or array of messages
   * @returns {Promise<string>} The response text
   */
  async prompt(input) {
    const messages = this._normalizeInput(input);
    return this.adapter.prompt(this, messages);
  }

  /**
   * Send a prompt and stream the response
   * @param {string|Array} input - Either a string (user message) or array of messages
   * @yields {string} Text chunks as they arrive
   */
  async *stream(input) {
    const messages = this._normalizeInput(input);
    yield* this.adapter.stream(this, messages);
  }

  /**
   * Normalize input to message array format
   * @private
   */
  _normalizeInput(input) {
    if (typeof input === 'string') {
      return [{ role: 'user', content: input }];
    }
    return input;
  }
}

// Provider adapters
LLM.adapters = {
  /**
   * OpenAI adapter (Chat Completions API)
   */
  openai: {
    async prompt(llm, messages) {
      const body = {
        model: llm.model,
        messages: llm.systemPrompt
          ? [{ role: 'system', content: llm.systemPrompt }, ...messages]
          : messages
      };

      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${llm.apiKey}`
        },
        body: JSON.stringify(body)
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        throw new Error(`OpenAI API error: ${error.error?.message || response.statusText}`);
      }

      const data = await response.json();
      return data.choices[0].message.content;
    },

    async *stream(llm, messages) {
      const body = {
        model: llm.model,
        messages: llm.systemPrompt
          ? [{ role: 'system', content: llm.systemPrompt }, ...messages]
          : messages,
        stream: true
      };

      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${llm.apiKey}`
        },
        body: JSON.stringify(body)
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        throw new Error(`OpenAI API error: ${error.error?.message || response.statusText}`);
      }

      yield* parseSSE(response, (data) => {
        if (data === '[DONE]') return null;
        const parsed = JSON.parse(data);
        return parsed.choices[0]?.delta?.content || '';
      });
    }
  },

  /**
   * Anthropic (Claude) adapter
   */
  anthropic: {
    async prompt(llm, messages) {
      const body = {
        model: llm.model,
        max_tokens: 4096,
        messages: messages.map(m => ({
          role: m.role === 'system' ? 'user' : m.role,
          content: m.content
        }))
      };

      if (llm.systemPrompt) {
        body.system = llm.systemPrompt;
      }

      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': llm.apiKey,
          'anthropic-version': '2023-06-01',
          'anthropic-dangerous-direct-browser-access': 'true'
        },
        body: JSON.stringify(body)
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        throw new Error(`Anthropic API error: ${error.error?.message || response.statusText}`);
      }

      const data = await response.json();
      return data.content[0].text;
    },

    async *stream(llm, messages) {
      const body = {
        model: llm.model,
        max_tokens: 4096,
        stream: true,
        messages: messages.map(m => ({
          role: m.role === 'system' ? 'user' : m.role,
          content: m.content
        }))
      };

      if (llm.systemPrompt) {
        body.system = llm.systemPrompt;
      }

      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': llm.apiKey,
          'anthropic-version': '2023-06-01',
          'anthropic-dangerous-direct-browser-access': 'true'
        },
        body: JSON.stringify(body)
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        throw new Error(`Anthropic API error: ${error.error?.message || response.statusText}`);
      }

      yield* parseSSE(response, (data) => {
        const parsed = JSON.parse(data);
        if (parsed.type === 'content_block_delta') {
          return parsed.delta?.text || '';
        }
        return '';
      });
    }
  },

  /**
   * Google Gemini adapter
   */
  gemini: {
    async prompt(llm, messages) {
      // Convert messages to Gemini format
      const contents = messages.map(m => ({
        role: m.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: m.content }]
      }));

      // If there's a system prompt, prepend it as a user message
      if (llm.systemPrompt) {
        contents.unshift({
          role: 'user',
          parts: [{ text: llm.systemPrompt }]
        });
        // Add a model acknowledgment to maintain alternating pattern
        contents.splice(1, 0, {
          role: 'model',
          parts: [{ text: 'Understood.' }]
        });
      }

      const url = `https://generativelanguage.googleapis.com/v1beta/models/${llm.model}:generateContent`;

      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-goog-api-key': llm.apiKey
        },
        body: JSON.stringify({ contents })
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        throw new Error(`Gemini API error: ${error.error?.message || response.statusText}`);
      }

      const data = await response.json();
      return data.candidates[0].content.parts[0].text;
    },

    async *stream(llm, messages) {
      // Convert messages to Gemini format
      const contents = messages.map(m => ({
        role: m.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: m.content }]
      }));

      // If there's a system prompt, prepend it
      if (llm.systemPrompt) {
        contents.unshift({
          role: 'user',
          parts: [{ text: llm.systemPrompt }]
        });
        contents.splice(1, 0, {
          role: 'model',
          parts: [{ text: 'Understood.' }]
        });
      }

      const url = `https://generativelanguage.googleapis.com/v1beta/models/${llm.model}:streamGenerateContent?alt=sse`;

      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-goog-api-key': llm.apiKey
        },
        body: JSON.stringify({ contents })
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({}));
        throw new Error(`Gemini API error: ${error.error?.message || response.statusText}`);
      }

      yield* parseSSE(response, (data) => {
        const parsed = JSON.parse(data);
        return parsed.candidates?.[0]?.content?.parts?.[0]?.text || '';
      });
    }
  }
};

/**
 * Parse Server-Sent Events from a fetch response
 * @param {Response} response - Fetch response with SSE body
 * @param {Function} extractor - Function to extract text from each data line
 * @yields {string} Extracted text chunks
 */
async function* parseSSE(response, extractor) {
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop(); // Keep incomplete line in buffer

      for (const line of lines) {
        if (line.startsWith('data: ')) {
          const data = line.slice(6);
          if (data.trim()) {
            try {
              const text = extractor(data);
              if (text) yield text;
            } catch (e) {
              // Skip malformed data
            }
          }
        }
      }
    }

    // Process any remaining buffer
    if (buffer.startsWith('data: ')) {
      const data = buffer.slice(6);
      if (data.trim()) {
        try {
          const text = extractor(data);
          if (text) yield text;
        } catch (e) {
          // Skip malformed data
        }
      }
    }
  } finally {
    reader.releaseLock();
  }
}

// Export for ES modules
export { LLM };

const scriptEl = document.querySelector('script[data-tool-search]');
const toolsJsonUrl = scriptEl ? new URL('tools.json', scriptEl.src).href : new URL('tools.json', window.location.href).href;

const ready = (callback) => {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', callback);
  } else {
    callback();
  }
};

const formatDate = (value) => {
  if (!value) {
    return '';
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
};

ready(() => {
  const heading = Array.from(document.querySelectorAll('h1')).find((element) =>
    element.textContent?.trim().toLowerCase().includes('tools.simonwillison.net'),
  );

  if (!heading) {
    return;
  }

  const style = document.createElement('style');
  style.textContent = `
    .tool-search-container {
      margin: 1.5rem 0 2rem;
      padding: 1.15rem 1.5rem 1rem;
      border-radius: 0.45rem;
      border: 1.5px solid #d9dce6;
      background: linear-gradient(180deg, #ffffff 0%, #fbfcff 100%);
    }
    .tool-search-label {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      border: 0;
    }
    .tool-search-input-wrapper {
      position: relative;
      margin-bottom: 0.95rem;
    }
    .tool-search-input-icon {
      position: absolute;
      top: 50%;
      left: 1.1rem;
      transform: translateY(-50%);
      width: 1rem;
      height: 1rem;
      color: #4c5a85;
      pointer-events: none;
    }
    .tool-search-input-icon svg {
      display: block;
      width: 100%;
      height: 100%;
    }
    #tool-search-input {
      width: 100%;
      box-sizing: border-box;
      border-radius: 0.7rem;
      border: 1.5px solid #94a3d4;
      background-color: rgba(255, 255, 255, 0.95);
      padding: 0.75rem 1rem 0.75rem 2.75rem;
      font-size: 1rem;
      line-height: 1.5;
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }
    #tool-search-input::placeholder {
      color: #4f5c83;
    }
    #tool-search-input:focus {
      outline: none;
      border-color: #3b4fd4;
      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18);
      background-color: #fff;
    }
    #tool-search-input:disabled {
      color: #6b6f80;
      background-color: rgba(250, 250, 255, 0.8);
    }
    .tool-search-hint {
      margin: 0 0 0;
      font-size: 0.875rem;
      color: #6f7796;
      max-width: 32rem;
    }
