    }
  `;
  document.head.appendChild(style);

  const container = document.createElement('section');
  container.className = 'tool-search-container';
  container.setAttribute('role', 'search');

  const label = document.createElement('label');
  label.className = 'tool-search-label';
  label.setAttribute('for', 'tool-search-input');
  label.textContent = 'Search tools';

  const inputWrapper = document.createElement('div');
  inputWrapper.className = 'tool-search-input-wrapper';

  const icon = document.createElement('span');
  icon.className = 'tool-search-input-icon';
  icon.setAttribute('aria-hidden', 'true');
  icon.innerHTML = `
    <svg viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg">
      <circle cx="9" cy="9" r="5.5" stroke="currentColor" stroke-width="1.5" fill="none" />
      <line x1="13.35" y1="13.35" x2="17" y2="17" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" />
    </svg>
  `;

  const input = document.createElement('input');
  input.type = 'search';
  input.id = 'tool-search-input';
  input.placeholder = 'Loading tools…';
  input.autocomplete = 'off';
  input.setAttribute('aria-autocomplete', 'list');
  input.setAttribute('aria-controls', 'tool-search-results');
  input.setAttribute('aria-expanded', 'false');
  input.setAttribute('aria-haspopup', 'listbox');
  input.setAttribute('role', 'combobox');
  input.disabled = true;

  inputWrapper.appendChild(icon);
  inputWrapper.appendChild(input);

  const hint = document.createElement('p');
  hint.className = 'tool-search-hint';
  hint.textContent = 'Start typing to search all tools. Press “/” to focus the search.';

  const results = document.createElement('ul');
  results.id = 'tool-search-results';
  results.className = 'tool-search-results';
  results.setAttribute('role', 'listbox');
  results.setAttribute('aria-label', 'Tool suggestions');
  results.hidden = true;

  const status = document.createElement('div');
  status.className = 'tool-search-status';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');

  container.appendChild(label);
  container.appendChild(inputWrapper);
  container.appendChild(hint);
  container.appendChild(results);
  container.appendChild(status);

  heading.insertAdjacentElement('afterend', container);

  let tools = [];
  let currentMatches = [];
  let activeIndex = -1;

  const getVisitCounts = () => {
    const STORAGE_KEY = 'tools_analytics';
    try {
      const analytics = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      const counts = {};
      analytics.forEach((visit) => {
        // Convert pathname slug (e.g., "/json-to-yaml.html") to tool slug (e.g., "json-to-yaml")
        let slug = visit.slug || '';
        slug = slug.replace(/^\//, '').replace(/\.html$/, '');
        if (slug) {
          counts[slug] = (counts[slug] || 0) + 1;
        }
      });
      return counts;
    } catch (e) {
      return {};
    }
  };

  const updateStatus = (message) => {
    status.textContent = message || '';
  };

  const clearResults = () => {
    results.innerHTML = '';
    results.hidden = true;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
    currentMatches = [];
    activeIndex = -1;
  };

  const highlightOption = (index) => {
    const options = results.querySelectorAll('.tool-search-option');
    options.forEach((option) => {
      option.classList.remove('active');
      option.setAttribute('aria-selected', 'false');
    });

    if (index < 0 || index >= options.length) {
      input.removeAttribute('aria-activedescendant');
      activeIndex = -1;
      return;
    }

    const option = options[index];
    option.classList.add('active');
    option.setAttribute('aria-selected', 'true');
    input.setAttribute('aria-activedescendant', option.id);
    option.scrollIntoView({ block: 'nearest' });
    activeIndex = index;
  };

  const navigateToTool = (tool, { newTab = false } = {}) => {
    if (!tool) {
      return;
    }
    const destination = tool.url || `${tool.slug}.html`;
    if (newTab) {
      window.open(destination, '_blank', 'noopener');
    } else {
      window.location.assign(destination);
    }
  };

  const renderMatches = (matches, query) => {
    results.innerHTML = '';
    currentMatches = matches.map((entry) => entry.tool);
    activeIndex = -1;

    if (!currentMatches.length) {
      const empty = document.createElement('li');
      empty.className = 'tool-search-empty';
      empty.textContent = `No tools match “${query}”.`;
      empty.setAttribute('role', 'option');
      empty.setAttribute('aria-selected', 'false');
      results.appendChild(empty);
      results.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      updateStatus(`No tools match ${query}.`);
      return;
    }

    currentMatches.forEach((tool, index) => {
      const option = document.createElement('li');
      option.className = 'tool-search-option';
      option.id = `tool-search-option-${index}`;
      option.setAttribute('role', 'option');
      option.setAttribute('aria-selected', 'false');

      const link = document.createElement('a');
      link.className = 'tool-search-option-link';
      link.href = tool.url || `${tool.slug}.html`;
      link.tabIndex = -1;

      const title = document.createElement('span');
      title.className = 'tool-search-option-title';
      title.textContent = tool.title || tool.slug;

      link.appendChild(title);

      if (tool.description) {
        const description = document.createElement('span');
        description.className = 'tool-search-option-description';
        description.textContent = tool.description;
        link.appendChild(description);
      }

      const metaBits = [];
      if (tool.updated) {
        metaBits.push(`Updated ${formatDate(tool.updated)}`);
      } else if (tool.created) {
        metaBits.push(`Created ${formatDate(tool.created)}`);
      }

      if (metaBits.length) {
        const meta = document.createElement('span');
        meta.className = 'tool-search-option-meta';
        meta.textContent = metaBits.join(' • ');
        link.appendChild(meta);
      }

      link.addEventListener('mousedown', (event) => {
        event.preventDefault();
      });

      link.addEventListener('click', (event) => {
        event.preventDefault();
        navigateToTool(tool, { newTab: event.metaKey || event.ctrlKey });
      });

      option.appendChild(link);
      results.appendChild(option);
    });

    results.hidden = false;
    input.setAttribute('aria-expanded', 'true');
    updateStatus(`${currentMatches.length} result${currentMatches.length === 1 ? '' : 's'} available.`);
  };

  const performSearch = () => {
    const query = input.value.trim();
    if (!query) {
      clearResults();
      updateStatus('Search cleared.');
      return;
    }

    const lowered = query.toLowerCase();
    const terms = lowered.split(/\s+/).filter(Boolean);
    const visitCounts = getVisitCounts();

    const ranked = tools
      .map((tool) => {
        const fields = [tool.title, tool.description, tool.slug]
          .filter(Boolean)
          .join(' ')
          .toLowerCase();

        if (!terms.every((term) => fields.includes(term))) {
          return null;
        }

        const title = (tool.title || '').toLowerCase();
        const slug = (tool.slug || '').toLowerCase();

        let score = 100;
        if (title.startsWith(lowered)) {
          score = 0;
        } else if (slug.startsWith(lowered)) {
          score = 10;
        } else if (title.includes(lowered)) {
          score = 20;
        } else if (slug.includes(lowered)) {
          score = 30;
        }

        const updated = tool.updated ? Date.parse(tool.updated) || 0 : 0;
        const visits = visitCounts[tool.slug] || 0;

        return { tool, score, updated, visits };
      })
      .filter(Boolean)
      .sort((a, b) => {
        // Sort by visits first (descending - more visits is better)
        if (a.visits !== b.visits) {
          return b.visits - a.visits;
        }
        // Then by score (ascending - lower is better)
        if (a.score !== b.score) {
          return a.score - b.score;
        }
        // Then by updated date (descending - newer is better)
        return b.updated - a.updated;
      })
      .slice(0, 12);

    renderMatches(ranked, query);
  };

  input.addEventListener('input', () => {
    if (!tools.length) {
      return;
    }
    performSearch();
  });

  input.addEventListener('keydown', (event) => {
    if (!currentMatches.length && !['Escape', 'Tab'].includes(event.key)) {
      return;
    }

    if (event.key === 'ArrowDown') {
      event.preventDefault();
      if (!results.hidden) {
        const nextIndex = (activeIndex + 1) % currentMatches.length;
        highlightOption(nextIndex);
      } else {
        performSearch();
      }
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      const nextIndex = activeIndex <= 0 ? currentMatches.length - 1 : activeIndex - 1;
      highlightOption(nextIndex);
    } else if (event.key === 'Enter') {
      if (!currentMatches.length) {
        return;
      }
      event.preventDefault();
      const chosen = activeIndex >= 0 ? currentMatches[activeIndex] : currentMatches[0];
      navigateToTool(chosen, { newTab: event.metaKey || event.ctrlKey });
    } else if (event.key === 'Escape') {
      clearResults();
      input.blur();
    }
  });

  input.addEventListener('focus', () => {
    if (input.value && currentMatches.length) {
      results.hidden = false;
      input.setAttribute('aria-expanded', 'true');
    }
  });

  input.addEventListener('blur', () => {
    window.setTimeout(() => {
      clearResults();
    }, 120);
  });

  document.addEventListener('click', (event) => {
    if (!container.contains(event.target)) {
      clearResults();
    }
  });

  document.addEventListener('keydown', (event) => {
    if (event.key !== '/' || event.altKey || event.ctrlKey || event.metaKey) {
      return;
    }

    const target = event.target;
    const tagName = target?.tagName?.toLowerCase();
    const isEditable = target?.isContentEditable;
    if (tagName === 'input' || tagName === 'textarea' || tagName === 'select' || isEditable) {
      return;
    }

    event.preventDefault();
    input.focus();
    input.select();
  });

  fetch(toolsJsonUrl)
    .then((response) => {
      if (!response.ok) {
        throw new Error(`Failed to load tools.json: ${response.status}`);
      }
      return response.json();
    })
    .then((data) => {
      if (!Array.isArray(data)) {
        throw new Error('tools.json did not return an array');
      }
      tools = data;
      input.placeholder = `Search ${tools.length} tools…`;
      input.disabled = false;
      updateStatus(`${tools.length} tools available to search.`);
      if (input === document.activeElement && input.value) {
        performSearch();
      }
    })
    .catch((error) => {
      console.error(error);
      input.placeholder = 'Search unavailable';
      input.disabled = true;
      updateStatus('Search unavailable.');
    });
});

#!/usr/bin/env -S uv run
# /// script
# requires-python = ">=3.10"
# dependencies = ["httpx"]
# ///
"""
List model IDs from OpenAI, Anthropic, and Gemini using httpx.

API keys are obtained via:
  llm keys get openai
  llm keys get anthropic
  llm keys get gemini

Providers whose key command fails are skipped.
"""

from __future__ import annotations

import json
import subprocess
import sys
from dataclasses import dataclass
from typing import Iterable, Optional

import httpx


@dataclass(frozen=True)
class ProviderResult:
    provider: str
    models: list[str]


def _get_key_via_llm(provider: str) -> Optional[str]:
    """
    Run: llm keys get <provider>
    Return the key string (stripped) or None if command fails.
    """
    try:
        proc = subprocess.run(
            ["llm", "keys", "get", provider],
            check=True,
            capture_output=True,
            text=True,
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        return None

    key = (proc.stdout or "").strip()
    return key or None


def _print_section(title: str) -> None:
    print("\n" + "=" * len(title))
    print(title)
    print("=" * len(title))


def list_openai_models(client: httpx.Client, api_key: str) -> ProviderResult:
    url = "https://api.openai.com/v1/models"
    headers = {"Authorization": f"Bearer {api_key}"}

    r = client.get(url, headers=headers)
    r.raise_for_status()
    data = r.json()

    models = []
    for m in data.get("data", []) or []:
        mid = m.get("id")
        if isinstance(mid, str):
            models.append(mid)

    models = sorted(set(models))
    return ProviderResult("openai", models)


def list_anthropic_models(client: httpx.Client, api_key: str) -> ProviderResult:
    url = "https://api.anthropic.com/v1/models"
    # Anthropic requires the anthropic-version header on API requests.
    headers = {
        "x-api-key": api_key,
        "anthropic-version": "2023-06-01",
    }

    models: list[str] = []
    after_id: Optional[str] = None

    while True:
        params = {}
        if after_id:
            params["after_id"] = after_id

        r = client.get(url, headers=headers, params=params)
        r.raise_for_status()
        payload = r.json()

        for m in payload.get("data", []) or []:
            mid = m.get("id")
            if isinstance(mid, str):
                models.append(mid)

        has_more = bool(payload.get("has_more"))
        after_id = payload.get("last_id") if has_more else None
        if not has_more or not isinstance(after_id, str) or not after_id:
            break

    models = sorted(set(models))
    return ProviderResult("anthropic", models)


def list_gemini_models(client: httpx.Client, api_key: str) -> ProviderResult:
    url = "https://generativelanguage.googleapis.com/v1beta/models"

    models: list[str] = []
    page_token: [REDACTED]] = None

    while True:
        params = {"key": api_key}
        if page_token:
            params["pageToken"] = page_token

        r = client.get(url, params=params)
        r.raise_for_status()
        payload = r.json()

        for m in payload.get("models", []) or []:
            # Gemini uses "name" like "models/gemini-2.0-flash"
            name = m.get("name")
            if isinstance(name, str):
                models.append(name)

        page_token = [REDACTED]"nextPageToken")
        if not isinstance(page_token, str) or not page_token:
            break

    models = sorted(set(models))
    return ProviderResult("gemini", models)


def main(argv: list[str]) -> int:
    # Optional: --json to emit machine-readable output.
    as_json = "--json" in argv

    # Try to get keys. Skip providers that error.
    keys = {
        "openai": _get_key_via_llm("openai"),
        "anthropic": _get_key_via_llm("anthropic"),
        "gemini": _get_key_via_llm("gemini"),
    }

    available = {k: v for k, v in keys.items() if v}
    if not available:
        print("No API keys found via `llm keys get {openai,anthropic,gemini}`. Nothing to do.", file=sys.stderr)
        return 2

    results: list[ProviderResult] = []

    with httpx.Client(timeout=httpx.Timeout(30.0)) as client:
        for provider, key in available.items():
            try:
                if provider == "openai":
                    results.append(list_openai_models(client, key))
                elif provider == "anthropic":
                    results.append(list_anthropic_models(client, key))
                elif provider == "gemini":
                    results.append(list_gemini_models(client, key))
            except httpx.HTTPError as e:
                # Don't kill the whole run if one provider fails.
                print(f"[{provider}] HTTP error: {e}", file=sys.stderr)
            except (ValueError, json.JSONDecodeError) as e:
                print(f"[{provider}] JSON parse error: {e}", file=sys.stderr)

    if as_json:
        out = {r.provider: r.models for r in results}
        print(json.dumps(out, indent=2, sort_keys=True))
        return 0

    # Pretty output
    for r in results:
        _print_section(f"{r.provider} ({len(r.models)} models)")
        for mid in r.models:
            print(mid)

    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""
ModelScope model size calculator

Usage: uv run modelscope_size.py https://modelscope.cn/models/Qwen/Qwen3-Coder-480B-A35B-Instruct-FP8
"""

import sys
import json
import urllib.request
import urllib.parse
from typing import Dict, Any


def parse_model_url(url: str) -> tuple[str, str]:
    """Extract namespace and model name from ModelScope URL"""
    if not url.startswith("https://modelscope.cn/models/"):
        raise ValueError("Invalid ModelScope model URL")

    path = url.replace("https://modelscope.cn/models/", "")
    parts = path.split("/")

    if len(parts) < 2:
        raise ValueError("URL must contain namespace/model format")

    namespace = parts[0]
    model = parts[1]

    return namespace, model


def fetch_model_files(namespace: str, model: str) -> Dict[str, Any]:
    """Fetch model files from ModelScope API"""
    api_url = f"https://modelscope.cn/api/v1/models/{namespace}/{model}/repo/files?Revision=master&Root="

    try:
        with urllib.request.urlopen(api_url) as response:
            data = json.loads(response.read().decode("utf-8"))
            return data
    except Exception as e:
        raise RuntimeError(f"Failed to fetch data from API: {e}")


def calculate_total_size(files_data: Dict[str, Any]) -> int:
    """Calculate total size of all files in bytes"""
    total_size = 0

    if "Data" not in files_data:
        raise ValueError("Invalid API response format")

    data = files_data["Data"]
    if "Files" not in data:
        raise ValueError("No Files found in API response")

    files = data["Files"]

    for file_info in files:
        if "Size" in file_info:
            total_size += file_info["Size"]

    return total_size


def bytes_to_gb(bytes_size: int) -> float:
    """Convert bytes to gigabytes"""
    return bytes_size / (1024**3)


def main():
    if len(sys.argv) != 2:
        print(
            "Usage: uv run modelscope_size.py <modelscope_model_url>", file=sys.stderr
        )
        sys.exit(1)

    model_url = sys.argv[1]

    try:
        namespace, model = parse_model_url(model_url)
        files_data = fetch_model_files(namespace, model)
        total_bytes = calculate_total_size(files_data)
        total_gb = bytes_to_gb(total_bytes)

        print(f"{total_gb:.1f} GB")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

